def to_codes(s):
    return ','.join('&H%04X' % ord(c) for c in s)


lines = ['Option Explicit', '', "' UI message text (code points avoid import encoding issues)", '']
for name, text in MESSAGES.items():
    lines.append('Public Function %s() As String' % name)
    lines.append('    Static cached As String')
    lines.append('    If cached = "" Then cached = CommonTextFromChars(%s)' % to_codes(text))
    lines.append('    %s = cached' % name)
    lines.append('End Function')
    lines.append('')

out = os.path.join(BASE, 'mod_UiMessages.bas')
with open(out, 'wb') as f:
    f.write(('\r\n'.join(lines) + '\r\n').encode('cp932'))
print('Wrote', out, len(MESSAGES), 'functions')
